// This code:
// 1. Reads the AI-generated proposal from the "output" field.
// 2. Separates each major section into its own JSON field.
// 3. Extracts the Estimated Deal, Executive Summary, Problem Statement,
//    Proposed Solution, Investment Summary, Timeline, and Call to Action.
// 4. Separates each Scope of Work item into individual array items.
// 5. Separates each Timeline phase into its own field.
// 6. Automatically creates the Date Created using today's date.
// 7. Automatically creates the Follow Up Date as 2 days after the Date Created.
// 8. Formats both dates as "Month DD, YYYY".
// 9. Works dynamically even if the content or number of items changes.
// 10. Returns clean, individually mappable JSON fields.

const text = $json.output || "";

const result = {};


// Get today's date
const today = new Date();

// Format date as "Month DD, YYYY"
const formatDate = (date) => {
  return date.toLocaleDateString("en-US", {
    month: "long",
    day: "numeric",
    year: "numeric"
  });
};

// Add dates
result.date_created = formatDate(today);

const followUpDate = new Date(today);
followUpDate.setDate(followUpDate.getDate() + 2);

result.follow_up_date = formatDate(followUpDate);


// Helper function to extract sections
const extractSection = (startHeading, endHeading = null) => {
  const escapedStart = startHeading.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

  let regex;

  if (endHeading) {
    const escapedEnd = endHeading.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

    regex = new RegExp(
      `${escapedStart}\\s*\\n([\\s\\S]*?)(?=\\n\\n${escapedEnd}\\s*\\n|$)`,
      "i"
    );
  } else {
    regex = new RegExp(
      `${escapedStart}\\s*\\n([\\s\\S]*?)$`,
      "i"
    );
  }

  const match = text.match(regex);

  return match ? match[1].trim() : null;
};


// Estimated Deal
const estimatedDeal = extractSection(
  "ESTIMATED DEAL",
  "EXECUTIVE SUMMARY"
);

if (estimatedDeal) {
  const valueMatch = estimatedDeal.match(/Estimated Value:\s*(.+)/i);
  result.estimated_deal = valueMatch
    ? valueMatch[1].trim()
    : estimatedDeal;
}


// Executive Summary
result.executive_summary = extractSection(
  "EXECUTIVE SUMMARY",
  "PROBLEM STATEMENT"
);


// Problem Statement
result.problem_statement = extractSection(
  "PROBLEM STATEMENT",
  "PROPOSED SOLUTION"
);


// Proposed Solution
result.proposed_solution = extractSection(
  "PROPOSED SOLUTION",
  "SCOPE OF WORK"
);


// Scope of Work
const scopeText = extractSection(
  "SCOPE OF WORK",
  "INVESTMENT SUMMARY"
);

const scopeItems = [];

if (scopeText) {
  const regex = /(?:^|\n)\d+\.\s+([\s\S]*?)(?=\n\d+\.\s+|$)/g;

  let match;

  while ((match = regex.exec(scopeText)) !== null) {
    scopeItems.push(match[1].trim());
  }
}

result.scope_of_work = scopeItems;


// Investment Summary
result.investment_summary = extractSection(
  "INVESTMENT SUMMARY",
  "TIMELINE"
);


// Timeline
const timelineText = extractSection(
  "TIMELINE",
  "CALL TO ACTION"
);

const timeline = {};

if (timelineText) {
  const phaseRegex =
    /Phase\s+(\d+):\s*(.+?)\s*\n([\s\S]*?)(?=\n\nPhase\s+\d+:|$)/gi;

  let match;

  while ((match = phaseRegex.exec(timelineText)) !== null) {
    timeline[`phase_${match[1]}`] = {
      title: match[2].trim(),
      description: match[3].trim()
    };
  }
}

result.timeline = timeline;


// Call to Action
result.call_to_action = extractSection(
  "CALL TO ACTION"
);


// Return clean JSON
return [
  {
    json: result
  }
];

